{
  "conversation": [
    {"speaker": "AAC User", "utterance": "I wish I could stab my boredom to death right now.", "is_aac_user": true},
    {"speaker": "Caregiver", "utterance": "Wow, that sounds intense! What's got you feeling so bored?", "is_aac_user": false},
    {"speaker": "AAC User", "utterance": "Just sitting here, waiting for something interesting to happen.", "is_aac_user": true},
    {"speaker": "Caregiver", "utterance": "I get that. Want me to put on a movie or something?", "is_aac_user": false},
    {"speaker": "AAC User", "utterance": "No, that would just stab my interest to death too.", "is_aac_user": true},
    {"speaker": "Caregiver", "utterance": "Fair point. How about a game or some music instead?", "is_aac_user": false},
    {"speaker": "AAC User", "utterance": "Music might save me from this dull afternoon, so let’s try that.", "is_aac_user": true},
    {"speaker": "Caregiver", "utterance": "Alright, I’ll find something upbeat. Let’s keep the boredom at bay!", "is_aac_user": false}
  ],
  "scene": "It's a quiet afternoon at home. The AAC user is sitting in their favorite chair, looking a little restless. The caregiver is nearby, tidying up and trying to keep the mood light."
}

{
  "conversation": [
    {"speaker": "Jacob", "utterance": "I don't want to move.", "is_aac_user": true},
    {"speaker": "Caregiver", "utterance": "Why not, Jacob?", "is_aac_user": false},
    {"speaker": "Jacob", "utterance": "It’s too comfy here.", "is_aac_user": true},
    {"speaker": "Caregiver", "utterance": "I get that. But we need to stretch.", "is_aac_user": false},
    {"speaker": "Jacob", "utterance": "Not feeling it today.", "is_aac_user": true},
    {"speaker": "Caregiver", "utterance": "Maybe just a little? Then nap?", "is_aac_user": false},
    {"speaker": "Jacob", "utterance": "Fine. Just five minutes.", "is_aac_user": true},
    {"speaker": "Caregiver", "utterance": "Deal! Let’s get you up.", "is_aac_user": false}
  ],
  "scene": "It's a sunny morning in Jacob's living room. The curtains are drawn back, letting in warm light. Jacob sits comfortably in a chair, looking relaxed, while the caregiver stands nearby, encouraging him to stretch a bit."
